/**
 * The order of the menus inside each group: what a person reaches for most comes first. A menu that is not listed keeps its place after the listed ones.
 */
function mcupr_cc_order() {
	return array(
		'content'  => array( 'posts', 'pages', 'media', 'events', 'notices', 'albums', 'videos', 'works', 'books', 'faq' ),
		'home'     => array( 'notice', 'home', 'sections', 'blocks', 'numbers' ),
		'look'     => array( 'identity', 'org', 'logos', 'colors', 'languages', 'menus', 'footer', 'credit', 'display', 'loading', 'print', 'customizer' ),
		'visitors' => array( 'messages', 'forum', 'forms', 'answers', 'polls', 'stats', 'social', 'policy', 'cookies' ),
		'students' => array( 'students', 'requests', 'student_grades', 'student_mail', 'student_import', 'student_codes', 'student_settings', 'student_log' ),
		'people'   => array( 'offices', 'groups', 'persons', 'staff_hub', 'units' ),
		'system'   => array( 'status', 'users', 'roles', 'login', 'images', 'files', 'insights', 'speed', 'elementor', 'settings_io', 'updates' ),
	);
}

/** The data with the menus in the order above (the keys stay; only the sequence of 'items' changes). */
function mcupr_cc_arrange( $d ) {
	$rank = array();
	$n    = 0;
	foreach ( array_keys( $d['cats'] ) as $cat ) {
		$list = mcupr_cc_order();
		foreach ( isset( $list[ $cat ] ) ? $list[ $cat ] : array() as $id ) {
			$rank[ $id ] = $n++;
		}
	}
	$pos = array();
	$i   = 0;
	foreach ( $d['items'] as $id => $it ) {
		$pos[ $id ] = isset( $rank[ $id ] ) ? $rank[ $id ] : 1000 + $i++;
	}
	uksort( $d['items'], static function ( $a, $b ) use ( $pos ) {
		return $pos[ $a ] <=> $pos[ $b ];
	} );
	return $d;
}
